values ('pm-vishwakarma', 'PM Vishwakarma', 'Concessional Loan', 'NATIONAL', 'Ministry of MSME & Ministry of Skill Development', 'DC-MSME', 'MSME-MSDE-VISHWAKARMA-2023', 'Holistic central scheme for end-to-end support to traditional artisans and craftspeople across 18 notified family trades with low-interest credit and modern toolkits.', 'Collateral-free enterprise credit up to ₹3 Lakh at an ultra-low 5% interest rate with ₹15,000 modern toolkit grant.', 'Support for artisans, tradespeople, and craftsmen with toolkits & credit', '₹1,00,000 – ₹3,00,000', 100000, 300000, 8, 50000, 5, 3, 0, 18, 60, 600000, ARRAY['SC', 'ST', 'OBC', 'General', 'Woman', 'Minority'], ARRAY['handicraft', 'manufacturing', 'services'], '{}', ARRAY['Aadhaar Card', 'Trade Skill Verification', 'Mobile linked to Aadhaar', 'Bank Account Details'], ARRAY['artisans', 'low-interest', 'toolkit', 'handicrafts'], ARRAY['Entrepreneurship', 'MSME', 'Business Loan', 'Subsidy', 'Grant', 'Credit Support', 'Equipment / Machinery', 'Manufacturing', 'Services', 'Handicrafts / Artisans', 'Skill & Self Employment'], 'https://pmvishwakarma.gov.in', 'Online via Portal', '10 August 2024', true, 1, '{"id":"pm-vishwakarma","name":"PM Vishwakarma Scheme for Traditional Artisans & Craftspeople","shortCode":"PM Vishwakarma","officialSchemeIdentifier":"MSME-MSDE-VISHWAKARMA-2023","sponsoringMinistry":"Ministry of MSME & Ministry of Skill Development","department":"DC-MSME","schemeType":"Concessional Loan","description":"Holistic central scheme for end-to-end support to traditional artisans and craftspeople across 18 notified family trades with low-interest credit and modern toolkits.","benefitSummary":"Collateral-free enterprise credit up to ₹3 Lakh at an ultra-low 5% interest rate with ₹15,000 modern toolkit grant.","fundingRangeText":"₹1,00,000 – ₹3,00,000","minAmount":100000,"maxAmount":300000,"subsidyRatePercent":8,"subsidyCap":50000,"baseInterestRate":5,"standardTenureYears":3,"moratoriumPeriodMonths":0,"targetCatego