values ('pm-mudra-tarun', 'PM MUDRA', 'Concessional Loan', 'NATIONAL', 'Ministry of Finance', 'Micro Units Development & Refinance Agency (MUDRA)', 'MOF-DFS-MUDRA-2015', 'Universal institutional credit facilitation for non-corporate, non-farm small and micro enterprises up to ₹10 Lakh without third-party collateral.', 'Collateral-free working capital and term loans from ₹50,000 up to ₹10 Lakhs without third-party guarantee.', 'Universal collateral-free business financing for micro-enterprises', '₹50,00,0 – ₹10,00,000', 50000, 1000000, 0, NULL, 9.2, 5, 6, 18, 65, 0, ARRAY['SC', 'ST', 'OBC', 'General', 'Woman', 'Minority'], ARRAY['trading', 'services', 'manufacturing', 'food', 'tech', 'agri', 'handicraft'], '{}', ARRAY['MUDRA Application Form', 'Proof of Identity & Address', 'Quotation of Machinery/Goods', 'Bank Account Statement (6 Months)'], ARRAY['collateral-free', 'working-capital', 'trading', 'services'], ARRAY['Entrepreneurship', 'MSME', 'Business Loan', 'Credit Support', 'Working Capital', 'Manufacturing', 'Services', 'Agriculture & Allied Enterprise', 'Handicrafts / Artisans'], 'https://www.mudra.org.in', 'Nodal Bank Branch', '05 July 2024', true, 1, '{"id":"pm-mudra-tarun","name":"Pradhan Mantri MUDRA Yojana (Tarun & Kishore Loans)","shortCode":"PM MUDRA","officialSchemeIdentifier":"MOF-DFS-MUDRA-2015","sponsoringMinistry":"Ministry of Finance","department":"Micro Units Development & Refinance Agency (MUDRA)","schemeType":"Concessional Loan","description":"Universal institutional credit facilitation for non-corporate, non-farm small and micro enterprises up to ₹10 Lakh without third-party collateral.","benefitSummary":"Collateral-free working capital and term loans from ₹50,000 up to ₹10 Lakhs without third-party guarantee.","fundingRangeText":"₹50,00,0 – ₹10,00,000","minAmount":50000,"maxAmount":1000000,"subsidyRatePercent":0,"baseInterestRate":9.2,"standardTenureYears":5,"moratoriumPeriodMonths":6,"targetCategories":["SC","ST","OBC","General","Woman","Minority"],"minAge":18,"maxAge":65,"maxAnnualIncomeCap":0,"targetBusinessTypes":["trading","services","manufacturing","food","tech","agri","handicraft"],"applicableStates":[],"requiredDocuments":["MUDRA Application Form","Proof of Identity & Address","Quotation of Machinery/Goods","Bank Account Statement (6 Months)"],"officialPortalUrl":"https://www.mudra.org.in","lastVerifiedDate":"05 July 2024","applicationMode":"Nodal Bank Branch","purpose":"Universal collateral-free business financing for micro-enterprises","tags":["collateral-free","working-capital","trading","services"],"fundingPurpose":"working_capital","mandatoryCriteria":["age","businessType"],"intelligence":{"identity":{"id":"pm-mudra-tarun","schemeName":"Pradhan Mantri MUDRA Yojana (Tarun & Kishore Loans)","shortCode":"PM MUDRA","officialSchemeIdentifier":"MOF-DFS-MUDRA-2015","sponsoringMinistry":"Ministry of Finance","department":"Micro Units Development & Refinance Agency (MUDRA)","schemeType":"Concessional Loan","description":"Collateral-free business loans for micro and small enterprises across Shishu (up to ₹50k), Kishore (₹50k-₹5L), and Tarun (₹5L-₹10L).","benefitSummary":"Collateral-free working capital and term loans from ₹50,000 up to ₹10 Lakhs without third-party guarantee."},"targeting":{"socialCategory":["SC","ST","OBC","General","Woman","Minority"],"genderTargeting":"any","businessType":["trading","services","manufacturing","food","tech","agri","handicraft"],"businessStage":["new","existing","expanding"],"enterpriseType":["micro"],"ruralUrbanApplicability":"all","stateApplicability":[],"sector":["msme_general","retail_trade","services_hospitality","food_processing"],"entrepreneurType":["general_entrepreneur","first_generation"]},"financial":{"minFunding":50000,"maxFunding":1000000,"fundingRangeText":"₹50,000 – ₹10,00,000","subsidyPercentage":0,"interestRate":9.2,"tenureYears":5,"moratoriumMonths":6,"creditGuarantee":{"covered":true,"percentage":75,"provider":"Credit Guarantee Fund for Micro Units 