ST"],"targetBusinessTypes":["manufacturing","food","tech"],"targetBusinessStages":["existing","expanding","new"],"applicableStates":[],"genderTargeting":"any","registrationRequirement":"udyam_required","enterpriseSize":["micro","small"],"mandatoryCriteria":["category","businessType"],"nonMandatoryCriteria":["income","age","state"],"otherMandatoryCriteria":["Proprietorship must be 100% owned by SC/ST; partnership/private limited must have at least 51% SC/ST shareholding","Machinery must be new and verified by technical inspection agency"]},"application":{"requiredDocuments":["Udyam Registration Certificate","Caste Certificate of Proprietor/Directors","Sanction Letter from Bank","Machinery Invoices"],"applicationMode":"Online via Portal","officialApplicationUrl":"https://www.scsthub.in","applicationProcess":["Avail term loan for plant and machinery from any Scheduled Commercial Bank","Lending bank uploads online subsidy claim on MSME SCLCSS portal","SIDBI / Nodal agency verifies documentary evidence and invoices","Subsidy released to lending bank and credited against loan principal"],"nodalAgency":"National Small Industries Corporation (NSIC) / National SC-ST Hub","bankChannelInformation":"All Scheduled Commercial Banks and SIDBI","helplineInformation":"NSSH Toll-Free: 1800-11-1955 / nssh@nsic.co.in"},"governance":{"officialSourceUrl":"https://www.scsthub.in","sourceName":"National SC-ST Hub, Ministry of MSME","sourceType":"statutory_guideline","lastVerifiedDate":"28 July 2024","verificationStatus":"verified","isActive":true,"dataVersion":"2.0.0","lastUpdatedDate":"2024-07-28","sourceNotes":"Active under National SC-ST Hub scheme guidelines."}},"scope":"NATIONAL","categories":["Entrepreneurship","MSME","Business Loan","Subsidy","Grant","Equipment / Machinery","Manufacturing","SC/ST Entrepreneurship","Technology / Digitalization"],"sourceProvenance":{"sourceName":"National SC-ST Hub, Ministry of MSME","sourceType":"statutory_guideline","officialSourceUrl":"https://www.