values ('vcf-sc', 'VCF-SC', 'Venture Capital', 'NATIONAL', 'Ministry of Social Justice & Empowerment', 'IFCI Venture Capital Funds Ltd.', 'MSJE-IFCI-VCFSC-2014', 'Promoting entrepreneurship among Scheduled Castes through long-term equity, quasi-equity, and debenture funding for innovative and growth-oriented companies.', 'Financial equity and quasi-equity assistance from ₹20 Lakhs to ₹15 Crores for innovative, high-growth SC companies.', 'High-growth equity and debt funding for SC founders', '₹20,00,000 – ₹15,00,00,000', 2000000, 150000000, 0, NULL, 7, 8, 24, 21, 65, 0, ARRAY['SC'], ARRAY['tech', 'manufacturing', 'services', 'food'], '{}', ARRAY['Company Incorporation Certificate (>51% SC owned)', 'Detailed Business Plan', 'Audited Financials (if existing)', 'Founder SC Proof'], ARRAY['sc', 'venture-capital', 'growth', 'tech'], ARRAY['Entrepreneurship', 'MSME', 'Startup', 'Manufacturing', 'Services', 'SC/ST Entrepreneurship', 'Technology / Digitalization'], 'https://www.vcfsc.in', 'Online via Portal', '02 August 2024', true, 1, '{"id":"vcf-sc","name":"Venture Capital Fund for Scheduled Castes (VCF-SC)","shortCode":"VCF-SC","officialSchemeIdentifier":"MSJE-IFCI-VCFSC-2014","sponsoringMinistry":"Ministry of Social Justice & Empowerment","department":"IFCI Venture Capital Funds Ltd.","schemeType":"Venture Capital","description":"Promoting entrepreneurship among Scheduled Castes through long-term equity, quasi-equity, and debenture funding for innovative and growth-oriented companies.","benefitSummary":"Financial equity and quasi-equity assistance from ₹20 Lakhs to ₹15 Crores for innovative, high-growth SC companies.","fundingRangeText":"₹20,00,000 – ₹15,00,00,000","minAmount":2000000,"maxAmount":150000000,"subsidyRatePercent":0,"baseInterestRate":7,"standardTenureYears":8,"moratoriumPeriodMonths":24,"targetCategories":["SC"],"minAge":21,"maxAge":65,"maxAnnualIncomeCap":0,"targetBusinessTypes":["tech","manufacturing","services","food"],"applicableStates":[],"requiredDoc