maxAge":65,"maxAnnualIncomeCap":0,"targetCategories":["SC"],"targetBusinessTypes":["tech","manufacturing","services","food"],"targetBusinessStages":["new","existing","scaling","expanding"],"applicableStates":[],"genderTargeting":"any","registrationRequirement":"gst_required","enterpriseSize":["small","medium"],"mandatoryCriteria":["category","age"],"nonMandatoryCriteria":["businessType","income","state"],"otherMandatoryCriteria":["Company must be registered under Companies Act, 2013 with at least 51% shareholding held by SC entrepreneurs","SC management control must be maintained throughout the tenure of investment"]},"application":{"requiredDocuments":["Company Incorporation Certificate (>51% SC owned)","Detailed Business Plan","Audited Financials (if existing)","Founder SC Proof"],"applicationMode":"Online via Portal","officialApplicationUrl":"https://www.vcfsc.in","applicationProcess":["Submit pitch deck and proposal on IFCI Venture portal","Initial screening and presentation before Investment Committee","Comprehensive financial and legal due diligence by IFCI Venture","Sanction and execution of Shareholders Agreement / Investment Agreement","Tranche-based capital infusion"],"nodalAgency":"IFCI Venture Capital Funds Limited","bankChannelInformation":"Direct equity / debenture investment by IFCI Venture","helplineInformation":"IFCI Venture Helpdesk: 011-41732502 / vcfsc@ifciventure.com"},"governance":{"officialSourceUrl":"https://www.vcfsc.in","sourceName":"IFCI Venture Capital Funds Ltd.","sourceType":"statutory_guideline","lastVerifiedDate":"02 August 2024","verificationStatus":"verified","isActive":true,"dataVersion":"2.0.0","lastUpdatedDate":"2024-08-02","sourceNotes":"Fund size enlarged with expanded mandate for greenfield tech startups."}},"scope":"NATIONAL","categories":["Entrepreneurship","MSME","Startup","Manufacturing","Services","SC/ST Entrepreneurship","Technology / Digitalization"],"sourceProvenance":{"sourceName":"IFCI Venture Capital Funds Ltd.","so