values ('cmegp-maharashtra', 'CMEGP (MH)', 'Loan + Subsidy', 'STATE_SPECIFIC', 'Industries Department, Govt. of Maharashtra', 'Directorate of Industries', 'GOM-IND-CMEGP-2019', 'State flagship self-employment program providing capital margin money subsidy up to 35% for micro-enterprises in Maharashtra.', 'State capital subsidy up to 35% with bank credit up to ₹50 Lakhs for micro-enterprises in Maharashtra.', 'Dedicated employment generation subsidy for Maharashtra-based micro-units', '₹2,00,000 – ₹50,00,000', 200000, 5000000, 35, 1750000, 8.5, 5, 6, 18, 45, 0, ARRAY['SC', 'ST', 'OBC', 'Woman', 'Minority', 'General'], ARRAY['manufacturing', 'services', 'agri', 'food', 'handicraft'], ARRAY['Maharashtra'], ARRAY['Maharashtra Domicile Certificate', 'Aadhaar Card', 'Project Report', 'Caste Certificate (if applicable)'], ARRAY['state-scheme', 'maharashtra', 'subsidy', 'manufacturing'], ARRAY['Entrepreneurship', 'MSME', 'Business Loan', 'Subsidy', 'Manufacturing', 'Services', 'Agriculture & Allied Enterprise', 'Handicrafts / Artisans'], 'https://maha-cmegp.gov.in', 'Online via Portal', '01 August 2024', true, 1, '{"id":"cmegp-maharashtra","name":"Chief Minister Employment Generation Programme (CMEGP Maharashtra)","shortCode":"CMEGP (MH)","officialSchemeIdentifier":"GOM-IND-CMEGP-2019","sponsoringMinistry":"Industries Department, Govt. of Maharashtra","department":"Directorate of Industries","schemeType":"Loan + Subsidy","description":"State flagship self-employment program providing capital margin money subsidy up to 35% for micro-enterprises in Maharashtra.","benefitSummary":"State capital subsidy up to 35% with bank credit up to ₹50 Lakhs for micro-enterprises in Maharashtra.","fundingRangeText":"₹2,00,000 – ₹50,00,000","minAmount":200000,"maxAmount":5000000,"subsidyRatePercent":35,"subsidyCap":1750000,"baseInterestRate":8.5,"standardTenureYears":5,"moratoriumPeriodMonths":6,"targetCategories":["SC","ST","OBC","Woman","Minority","General"],"minAge":18,"maxAge":45,"maxAnnualIncomeCap":0,"targetBusinessTypes":["manufacturing","services","agri","food","handicraft"],"applicableStates":["Maharashtra"],"requiredDocuments":["Maharashtra Domicile Certificate","Aadhaar Card","Project Report","Caste Certificate (if applicable)"],"officialPortalUrl":"https://maha-cmegp.gov.in","lastVerifiedDate":"01 August 2024","applicationMode":"Online via Portal","purpose":"Dedicated employment generation subsidy for Maharashtra-based micro-units","tags":["state-scheme","maharashtra","subsidy","manufacturing"],"fundingPurpose":"greenfield_setup","mandatoryCriteria":["state","businessType","age"],"intelligence":{"identity":{"id":"cmegp-maharashtra","schemeName":"Chief Minister Employment Generation Programme (CMEGP Maharashtra)","shortCode":"CMEGP (MH)","officialSchemeIdentifier":"GOM-IND-CMEGP-2019","sponsoringMinistry":"Industries Department, Govt. of Maharashtra","department":"Directorate of Industries","schemeType":"Loan + Subsidy","description":"Maharashtra state government scheme modeled on PMEGP providing margin money subsidy and interest subvention.","benefitSummary":"State capital subsidy up to 35% with bank credit up to ₹50 Lakhs for micro-enterprises in Maharashtra."},"targeting":{"socialCategory":["SC","ST","OBC","Woman","Minority","General"],"genderTargeting":"any","businessType":["manufacturing","services","agri","food","handicraft"],"businessStage":["new"],"enterpriseType":["micro"],"ruralUrbanApplicability":"all","stateApplicability":["Maharashtra"],"sector":["msme_general","food_processing","textiles_handicrafts","services_hospitality"],"entrepreneurType":["first_generation","youth_promoter"]},"financial":{"minFunding":200000,"maxFunding":5000000,"fundingRangeText":"₹2,00,000 – ₹50,00,000","subsidyPercentage":35,"subsidyCap":1750000,"interestRate":8.5,"tenureYears":5,"moratoriumMonths":6,"marginContribution":"5% for special categories (SC/ST/OBC/Women/Minority), 10% for General","otherFinancialBenefits":["Rural projects get 35% subsidy, urban projects get 25% subsidy","Interest subvention of 5% for prompt repayment"]},"eligibility":{"minAge":18,"maxAge":45,"maxAnnualIncomeCap":0,"targetCategories":["SC","ST","OBC","Woman","Minority","General"],"targetBusinessTypes":["manufacturing","services","agri","food","handicraft"],"targetBusinessStages":["new"],"applicableStates":["Maharashtra"],"genderTargeting":"any","registrationRequirement":"none","enterpriseSize":["micro"],"mandatoryCriteria":["state","businessType","age"],"nonMandatoryCriteria":["category","income"],"otherMandatoryCriteria":["Applicant must possess valid Domicile Certificate of Maharashtra","Minimum educational qualification 7th pass for projects above ₹10 Lakhs"]},"application":{"requiredDocuments":["Maharashtra Domicile Certificate","Aadhaar Card","Project Report","Caste Certificate (if applicable)"],"applicationMode":"Online via Portal","officialApplicationUrl":"https://maha-cmegp.gov.in","applicationProcess":["Register on maha-cmegp.gov.in portal with Aadhaar and domicile proof","District Industry Center (DIC) verifies application and project viability","Financing bank conducts credit assessment and issues loan sanction","Mandatory 2-week EDP training through MITCON or MCED","Subsidy released to lock-in bank account"],"nodalAgency":"Directorate of Industries, Maharashtra & KVIB","bankChannelInformation":"All Scheduled Commercial Banks and Maharashtra Gramin Bank","helplineInformation":"Maha-CMEGP Toll-Free: 1800-120-8040 / support.cmegp@maharashtra.gov.in"},"governance":{"officialSourceUrl":"https://maha-cmegp.gov.in","sourceName":"Directorate of Industries, Government of Maharashtra","sourceType":"statutory_guideline","lastVerifiedDate":"01 August 2024","verificationStatus":"verified","isActive":true,"dataVersion":"2.0.0","lastUpdatedDate":"2024-08-01","sourceNotes":"Maharashtra Government Resolution (GR) Industries Dept 2019, amended 2023."}},"scope":"STATE_SPECIFIC","categories":["Entrepreneurship","MSME","Business Loan","Subsidy","