% for SC/ST/BC/MBC/Minorities/Women","otherFinancialBenefits":["3% interest subvention for the entire repayment tenure","Project cost ceiling enhanced up to ₹5 Crore"]},"eligibility":{"minAge":21,"maxAge":45,"maxAnnualIncomeCap":0,"targetCategories":["SC","ST","Woman","OBC","Minority","General"],"targetBusinessTypes":["manufacturing","services","food","tech"],"targetBusinessStages":["new"],"applicableStates":["Tamil Nadu"],"genderTargeting":"any","registrationRequirement":"none","enterpriseSize":["micro","small"],"mandatoryCriteria":["state","age","businessType"],"nonMandatoryCriteria":["category","income"],"otherMandatoryCriteria":["Must be a first-generation entrepreneur (no existing family enterprise in same sector)","Must hold a Degree, Diploma, or ITI certificate from a recognized institution","Age relaxed up to 45 years for special categories (SC/ST/BC/MBC/Women/Differently Abled)"]},"application":{"requiredDocuments":["Tamil Nadu Resident Proof","Degree/Diploma Certificate","Project Feasibility Report","Bank Consent Letter"],"applicationMode":"Online via Portal","officialApplicationUrl":"https://msmeonline.tn.gov.in/needs","applicationProcess":["Apply online via msmeonline.tn.gov.in/needs","District Task Force Committee (DTFC) headed by District Collector interviews applicants","Selection and referral to Tamil Nadu Industrial Investment Corporation (TIIC) or commercial banks","Mandatory Entrepreneurship Training by EDII Tamil Nadu","Subsidy sanctioned and credited directly to loan account"],"nodalAgency":"Directorate of Industries and Commerce & TIIC","bankChannelInformation":"Commercial Banks and Tamil Nadu Industrial Investment Corporation (TIIC)","helplineInformation":"TN MSME Helpdesk: 044-22501011 / dic-msme@tn.gov.in"},"governance":{"officialSourceUrl":"https://msmeonline.tn.gov.in/needs","sourceName":"MSME Department, Government of Tamil Nadu","sourceType":"statutory_guideline","lastVerifiedDate":"25 July 2024","verificationStatus":"verified","isActive