values ('ap-ysr-cheyutha', 'YSR-CHEYUTHA', 'Grant', 'STATE_SPECIFIC', 'Women Development and Child Welfare Department, Andhra Pradesh', 'Society for Elimination of Rural Poverty (SERP)', 'GOAP-WDCW-CHEYUTHA-2020', 'Financial assistance and enterprise incubation targeting women aged 45 to 60 from SC, ST, BC, and Minority communities, providing direct capital grants combined with corporate value-chain tie-ups (Amul, ITC, HUL, P&G) to set up sustainable retail, dairy, and grocery enterprises.', 'Direct financial assistance of ₹18,750 per year (total ₹75,000 across 4 years) coupled with institutional enterprise support, bank credit linkage, and input supply agreements.', NULL, '₹18,750 – ₹75,000', 18750, 75000, 100, 75000, 0, 4, 0, 45, 60, 120000, ARRAY['Woman', 'SC', 'ST', 'OBC', 'Minority'], ARRAY['trading', 'food', 'agri', 'services'], ARRAY['Andhra Pradesh'], ARRAY['Aadhaar Card of Woman Beneficiary (age 45-60 verification)', 'Community Certificate (SC, ST, BC, or Minority) issued by Tahsildar', 'Integrated Income Certificate / White Ration Card', 'Bank Account Passbook with Aadhaar linkage'], ARRAY['Women', 'Micro-Enterprise', 'Livelihood', 'Andhra Pradesh', 'Direct Grant'], ARRAY['Entrepreneurship', 'MSME', 'Business Loan', 'Subsidy', 'Grant', 'Services', 'Agriculture & Allied Enterprise', 'Women Entrepreneurship', 'SC/ST Entrepreneurship', 'Rural Entrepreneurship', 'Technology / Digitalization'], 'https://navasakam.ap.gov.in', 'Hybrid', '2025-01-17', true, 1, '{"id":"ap-ysr-cheyutha","name":"YSR Cheyutha (Women Sustainable Livelihood & Micro-Enterprise Scheme)","shortCode":"YSR-CHEYUTHA","officialSchemeIdentifier":"GOAP-WDCW-CHEYUTHA-2020","sponsoringMinistry":"Women Development and Child Welfare Department, Andhra Pradesh","department":"Society for Elimination of Rural Poverty (SERP)","schemeType":"Grant","description":"Financial assistance and enterprise incubation targeting women aged 45 to 60 from SC, ST, BC, and Minority communities, providing direct capital grants combined with corporate value-chain tie-ups (Amul, ITC, HUL, P&G) to set up sustainable retail, dairy, and grocery enterprises.","benefitSummary":"Direct financial assistance of ₹18,750 per year (total ₹75,000 across 4 years) coupled with institutional enterprise support, bank credit linkage, and input supply agreements.","fundingRangeText":"₹18,750 – ₹75,000","minAmount":18750,"maxAmount":75000,"subsidyRatePercent":100,"subsidyCap":75000,"baseInterestRate":0,"standardTenureYears":4,"moratoriumPeriodMonths":0,"targetCategories":["Woman","SC","ST","OBC","Minority"],"minAge":45,"maxAge":60,"maxAnnualIncomeCap":120000,"targetBusinessTypes":["trading","food","agri","services"],"applicableStates":["Andhra Pradesh"],"requiredDocuments":["Aadhaar Card of Woman Beneficiary (age 45-60 verification)","Community Certificate (SC, ST, BC, or Minority) issued by Tahsildar","Integrated Income Certificate / White Ration Card","Bank Account Passbook with Aadhaar linkage"],"officialPortalUrl":"https://navasakam.ap.gov.in","lastVerifiedDate":"2025-01-17","applicationMode":"Hybrid","isWomenSpecific":true,"tags":["Women","Micro-Enterprise","Livelihood","Andhra Pradesh","Direct Grant"],"fundingPurpose":"women_entrepreneurship","mandatoryCriteria":["state","category","age"],"intelligence":{"identity":{"id":"ap-ysr-cheyutha","schemeName":"YSR Cheyutha (Women Sustainable Livelihood & Micro-Enterprise Scheme)","shortCode":"YSR-CHEYUTHA","officialSchemeIdentifier":"GOAP-WDCW-CHEYUTHA-2020","sponsoringMinistry":"Women Development and Child Welfare Department, Andhra Pradesh","department":"Society for Elimination of Rural Poverty (SERP)","schemeType":"Grant","description":"Financial assistance and enterprise incubation for women aged 45-60.","benefitSummary":"₹18,750/year (total ₹75,000) with corporate market linkages for retail & dairy units."},"targeting":{"socialCategory":["Woman","SC","ST","OBC","Minority"],"genderTargeting":"women_only","businessType":["trading","food","agri","services"],"businessStage":["new","expanding"],"enterpriseType":["nano_informal","micro"],"ruralUrbanApplicability":"all","stateApplicability":["Andhra Pradesh"],"sector":["retail_trade","food_processing","agriculture_allied"],"entrepreneurType":["first_generation","shg_member"]},"financial":{"minFunding":18750,"maxFunding":75000,"fundingRangeText":"₹18,750 – ₹75,000","subsidyPercentage":100,"subsidyCap":75000,"interestRate":0,"tenureYears":4,"moratoriumMonths":0},"eligibility":{"minAge":45,"maxAge":60,"maxAnnualIncomeCap":120000,"targetCategories":["Woman","SC","ST","OBC","Minority"],"targetBusinessTypes":["trading","food","agri","services"],"applicableStates":["Andhra Pradesh"],"registrationRequirement":"none","mandatoryCriteria":["state","category","age"]},"application":{"requiredDocuments":["Aadhaar Card (age 45-60)","Community Certificate (SC/ST/BC/Minority)","Income Certificate / White Ration Card","Bank Account Passbook"],"applicationMode":"Hybrid","officialApplicationUrl":"https://navasakam.ap.gov.in","nodalAgency":"Grama / Ward Volunteer & SERP Andhra Pradesh"},"governance":{"officialSourceUrl":"https://navasakam.ap.gov.in","sourceName":"YSR Cheyutha Operational Directives","sourceType":"statutory_guideline","lastVerifiedDate":"2025-01-17","verificationStatus":"verified","isActive":true,"dataVersion":"v2.0-ap","lastUpdatedDate":"2025-01-17"}},"scope":"STATE_SPECIFIC","categories":["Entrepreneurship","MSME","Business Loan","Subsidy","Grant","Services","Agriculture & Allied Enterprise","Women Entrepreneurship","SC/ST Entrepreneurship","Rural Entrepreneurship","Technology / Digitalization"],"sourceProvenance":{"sourceName":"YSR Cheyutha Operational Directives","sourceType":"statutory_guideline","officialSourceUrl":"https://navasakam.ap.gov.in","isOfficialGovernmentSource":true,"priorityLevel":2,"verificationStatus":"VERIFIED","lastVerifiedDate":"2025-01-17","sourceNotes":"Statutory ministry guidelines verified on official portal"},"trustProfile":{"source":{"source