insert into public.scheme_translations (scheme_id, lang, name, sponsoring_ministry, department, scheme_type, benefit_summary, funding_range_text, required_documents, last_verified_date)
values ('pmegp-msme', 'ta', 'பிரதமரின் வேலைவாய்ப்பு உருவாக்கும் திட்டம் (PMEGP)', 'மத்திய குறு, சிறு மற்றும் நடுத்தர தொழில் அமைச்சகம் (MSME)', 'கதர் மற்றும் கிராமத் தொழில்கள் ஆணையம் (KVIC)', 'கடன் + மானியம்', 'புதிய குறு நிறுவனங்களுக்கு ₹50 லட்சம் வரை வங்கி கடனுடன் 35% வரை நேரடி மூலதன மானியம்.', '₹2,00,000 – ₹50,00,000', ARRAY['ஆதார் அட்டை', 'சாதி / சமூக சான்றிதழ் (SC/ST/OBC/Minority)', 'விரிவான திட்ட அறிக்கை (DPR)', 'தொழில்முனைவோர் பயிற்சி (EDP) சான்றிதழ்', 'வங்கி கணக்கு புத்தகம் & கல்வி தகுதி சான்று'], 'ஆகஸ்ட் 2024')
