    last_verified_date = EXCLUDED.last_verified_date;
insert into public.scheme_translations (scheme_id, lang, name, sponsoring_ministry, department, scheme_type, benefit_summary, funding_range_text, required_documents, last_verified_date)
values ('standup-india', 'ta', 'பட்டியல் சாதி/பழங்குடி & பெண் தொழில்முனைவோருக்கான ஸ்டாண்ட்-அப் இந்தியா திட்டம்', 'நிதி அமைச்சகம் & சிட்பி (SIDBI)', 'நிதி சேவைகள் துறை', 'சலுகைக் கடன்', 'உற்பத்தி, சேவை அல்லது வர்த்தக நிறுவனங்களுக்கு 15% விளிம்புத் தொகையுடன் ₹10 லட்சம் முதல் ₹1 கோடி வரை வங்கி கடன்.', '₹10,00,000 – ₹1,00,00,000', ARRAY['ஆதார் & பான் அட்டை', 'சாதி சான்றிதழ் (SC/ST) / பெண் அடையாள சான்று', 'வணிக இடம் / நில உரிமை சான்று', 'உள்ளாட்சி / மாசுக்கட்டுப்பாட்டு வாரிய தடையின்மை சான்று (NOC)', 'விரிவான திட்ட அறிக்கை (DPR)'], 'ஜூலை 2024')
