insert into public.scheme_translations (scheme_id, lang, name, sponsoring_ministry, department, scheme_type, benefit_summary, funding_range_text, required_documents, last_verified_date)
values ('pm-vishwakarma', 'ta', 'பாரம்பரிய கைவினைஞர்களுக்கான பிரதம மந்திரி விஸ்வகர்மா திட்டம்', 'மத்திய குறு, சிறு மற்றும் நடுத்தர தொழில் அமைச்சகம் (MSME)', 'திறன் மேம்பாடு மற்றும் தொழில்முனைவோர் அமைச்சகம்', 'சலுகைக் கடன்', 'எவ்வித பிணையமும் இன்றி 5% சலுகை வட்டியில் ₹3 லட்சம் வரை கடன் மற்றும் ₹15,000 நவீன உபகரண உதவி.', '₹1,00,000 – ₹3,00,000', ARRAY['ஆதார் அட்டை', 'பாரம்பரிய கைவினைஞர் திறன் சரிபார்ப்பு (கிராம பஞ்சாயத்து / நகராட்சி)', 'ஆதாருடன் இணைக்கப்பட்ட மொபைல் எண்', 'செயலில் உள்ள வங்கி கணக்கு விவரம்'], 'ஆகஸ்ட் 2024')
on conflict (scheme_id, lang) do update set
    name = EXCLUDED.name,
    sponsoring_ministry = EXCLUDED.sponsoring_ministry,
    department = EXCLUDED.department,
    scheme_type = EXCLUDED.scheme_type,
    benefit_summary = EXCLUDED.benefit_summary,
    funding_range_text = EXCLUDED.funding_range_text,
    required_documents = EXCLUDED.required_documents,
    last_verified_date = EXCLUDED.last_verified_date;
insert into public.scheme_translations (scheme_id, lang, name, sponsoring_ministry, department, scheme_type, benefit_summary, funding_range_text, required_documents, last_verified_date)
values ('mahila-samridhi', 'ta', 'மகிளா சம்ரிதி யோஜனா (மகளிருக்கான சலுகை நுண்கடன்)', 'சமூக நீதி மற்றும் அதிகாரமளித்தல் அமைச்சகம்', 'NBCFDC / NSFDC', 'சலுகைக் கடன்', 'பிற்படுத்தப்பட்ட மற்றும் SC பெண் தொழில்முனைவோருக்கு ஆண்டுக்கு 4% சலுகை வட்டியில் ₹1.4 லட்சம் வரை நேரடி கடன்.', '₹50,000 – ₹1,40,000', ARRAY['குடும்ப ஆண்டு வருமான சான்றிதழ் (<₹3 லட்சம்)', 'சாதி / சமூக சான்றிதழ் (OBC/SC/ST)', 'ஆதார் அட்டை & இருப்பிட சான்று', 'சுய உதவிக்குழு (SHG) / தனிநபர் KYC விவரங்கள்'], 'ஜூன் 2024')
