insert into public.scheme_translations (scheme_id, lang, name, sponsoring_ministry, department, scheme_type, benefit_summary, funding_range_text, required_documents, last_verified_date)
values ('pm-mudra-tarun', 'ta', 'பிரதம மந்திரி முத்ரா திட்டம் (தருண் & கிஷோர் கடன்)', 'நிதி அமைச்சகம் (நிதி சேவைகள் துறை)', 'மைக்ரோ யூனிட்ஸ் டெவலப்மெண்ட் & ரீஃபைனான்ஸ் ஏஜென்சி (MUDRA)', 'சலுகைக் கடன்', 'எந்தவித சொத்து பிணையமும் இன்றி ₹50,000 முதல் ₹10 லட்சம் வரை பிணையில்லா நடைமுறை மூலதனம் மற்றும் இயந்திர கடன்.', '₹50,000 – ₹10,00,000', ARRAY['முத்ரா விண்ணப்பப் படிவம்', 'அடையாளம் & இருப்பிட சான்றிதழ்', 'இயந்திரங்கள் / உபகரணங்களுக்கான விலைப்புள்ளி (கொட்டேஷன்)', 'கடந்த 6 மாத வங்கி கணக்கு அறிக்கை'], 'ஆகஸ்ட் 2024')
on conflict (scheme_id, lang) do update set
