insert into public.scheme_translations (scheme_id, lang, name, sponsoring_ministry, department, scheme_type, benefit_summary, funding_range_text, required_documents, last_verified_date)
values ('tn-needs', 'ta', 'புதிய தொழில்முனைவோர் மற்றும் தொழில் நிறுவன மேம்பாட்டு திட்டம் (NEEDS தமிழ்நாடு)', 'குறு, சிறு மற்றும் நடுத்தர தொழில் நிறுவனங்கள் துறை, தமிழ்நாடு அரசு', 'தொழில் வணிக ஆணையரகம் & மாவட்ட தொழில் மையம் (DIC தமிழ்நாடு)', 'கடன் + மானியம்', 'பட்டதாரி முதல் தலைமுறை தொழில்முனைவோருக்கு ₹5 கோடி வரையிலான உற்பத்தி/சேவை திட்டங்களுக்கு 25% மூலதன மானியம் (அதிகபட்சம் ₹75 லட்சம்) மற்றும் 3% வட்டி தள்ளுபடி.', '₹10,00,000 – ₹5,00,00,000', ARRAY['தமிழ்நாடு நிரந்தர இருப்பிட சான்றிதழ்', 'பட்டப்படிப்பு அல்லது டிப்ளமோ சான்றிதழ்', 'விரிவான திட்ட சாத்தியக்கூறு அறிக்கை (DPR)', 'வங்கி கடன் கொள்கை அளவிலான ஒப்புதல் கடிதம்'], 'ஜூலை 2024')
