insert into public.scheme_translations (scheme_id, lang, name, sponsoring_ministry, department, scheme_type, benefit_summary, funding_range_text, required_documents, last_verified_date)
values ('cgtmse-guarantee', 'ta', 'குறு மற்றும் சிறு நிறுவனங்களுக்கான கடன் உத்தரவாத நிதி அறக்கட்டளை (CGTMSE)', 'மத்திய குறு, சிறு மற்றும் நடுத்தர தொழில் அமைச்சகம் (MSME)', 'கிரெடிட் கியாரண்டி டிரஸ்ட் (SIDBI & MSME)', 'கடன் உத்தரவாதம்', 'பெண்கள், SC/ST தொழில்முனைவோருக்கு ₹5 கோடி வரையிலான பிணையில்லா கடன்களுக்கு 85% வரை கடன் உத்தரவாதம்.', '₹5,00,000 – ₹5,00,00,000', ARRAY['உத்யம் பதிவு சான்றிதழ்', 'நிறுவனர்களின் பான் மற்றும் ஆதார் அட்டை', 'திட்ட சாத்தியக்கூறு அறிக்கை', 'ஜிஎஸ்டி தாக்கல் & வங்கி கணக்கு அறிக்கை'], 'ஆகஸ்ட் 2024')
