insert into public.scheme_translations (scheme_id, lang, name, sponsoring_ministry, department, scheme_type, benefit_summary, funding_range_text, required_documents, last_verified_date)
values ('pmegp-msme', 'te', 'ప్రధాన మంత్రి ఉపాధి కల్పన కార్యక్రమం (PMEGP)', 'సూక్ష్మ, చిన్న & మధ్య తరహా పరిశ్రమల మంత్రిత్వ శాఖ (MSME)', 'ఖాదీ మరియు గ్రామీణ పరిశ్రమల కమిషన్ (KVIC)', 'రుణం + సబ్సిడీ', 'కొత్త సూక్ష్మ పరిశ్రమలకు ₹50 లక్షల వరకు బ్యాంకు రుణం మరియు 35% వరకు ప్రత్యక్ష మూలధన సబ్సిడీ.', '₹2,00,000 – ₹50,00,000', ARRAY['ఆధార్ కార్డు', 'కుల / సామాజిక ధృవీకరణ పత్రం (SC/ST/OBC/Minority)', 'సమగ్ర ప్రాజెక్ట్ నివేదిక (DPR)', 'వ్యవస్థాపక శిక్షణ (EDP) సర్టిఫికేట్', 'బ్యాంక్ పాస్‌బుక్ & విద్యార్హత పత్రాలు'], 'ఆగస్టు 2024')
on conflict (scheme_id, lang) do update set
    name = EXCLUDED.name,
    sponsoring_ministry = EXCLUDED.sponsoring_ministry,
    department = EXCLUDED.department,
    scheme_type = EXCLUDED.scheme_type,
    benefit_summary = EXCLUDED.benefit_summary,
    funding_range_text = EXCLUDED.funding_range_text,
    required_documents = EXCLUDED.required_documents,
    last_verified_date = EXCLUDED.last_verified_date;
insert into public.scheme_translations (scheme_id, lang, name, sponsoring_ministry, department, scheme_type, benefit_summary, funding_range_text, required_documents, last_verified_date)
values ('standup-india', 'te', 'ఎస్సీ/ఎస్టీ మరియు మహిళా వ్యవస్థాపకుల కోసం స్టాండ్-అప్ ఇండియా పథకం', 'ఆర్థిక మంత్రిత్వ శాఖ & సిడ్బీ (SIDBI)', 'ఆర్థిక సేవల విభాగం', 'రాయితీ రుణం', 'తయారీ, సేవలు లేదా వ్యాపార రంగాలలో కొత్త యూనిట్లకు 15% రాయితీ మార్జిన్‌తో ₹10 లక్షల నుండి ₹1 కోటి వరకు బ్యాంకు రుణం.', '₹10,00,000 – ₹1,00,00,000', ARRAY['ఆధార్ మరియు పాన్ కార్డు', 'కుల ధృవీకరణ పత్రం (SC/ST) / మహిళా గుర్తింపు రుజువు', 'వ్యాపార స్థలం / భూమి యాజమాన్య రుజువు', 'మున్సిపల్ / కాలుష్య నియంత్రణ అనుమతి పత్రం (NOC)', 'సమగ్ర ప్రాజెక్ట్ నివేదిక (DPR)'], 'జూలై 2024')
on conflict (scheme_id, lang) do update set
    name = EXCLUDED.name,
    sponsoring_ministry = EXCLUDED.sponsoring_ministry,
    department = EXCLUDED.department,
    scheme_type = EXCLUDED.scheme_type,
    benefit_summary = EXCLUDED.benefit_summary,
    funding_range_text = EXCLUDED.funding_range_text,
    required_documents = EXCLUDED.required_documents,
    last_verified_date = EXCLUDED.last_verified_date;
insert into public.scheme_translations (scheme_id, lang, name, sponsoring_ministry, department, scheme_type, benefit_summary, funding_range_text, required_documents, last_verified_date)
values ('pm-vishwakarma', 'te', 'సంప్రదాయ కళాకారులు & చేతివృత్తుల వారి కోసం పీఎం విశ్వకర్మ పథకం', 'సూక్ష్మ, చిన్న & మధ్య తరహా పరిశ్రమల మంత్రిత్వ శాఖ (MSME)', 'నైపుణ్యాభివృద్ధి మరియు వ్యవస్థాపకత మంత్రిత్వ శాఖ', 'రాయితీ రుణం', 'ఎటువంటి పూచీకత్తు లేకుండా 5% రాయితీ వడ్డీతో ₹3 లక్షల వరకు రుణం మరియు ₹15,000 ఆధునిక పరికరాల సహాయం.', '₹1,00,000 – ₹3,00,000', ARRAY['ఆధార్ కార్డు', 'సంప్రదాయ కళాకారుల నైపుణ్య ధృవీకరణ (గ్రామ పంచాయతీ / పట్టణ సంస్థ)', 'ఆధార్‌తో లింక్ చేయబడిన మొబైల్ నంబర్', 'క్రియాశీల బ్యాంకు ఖాతా వివరాలు'], 'ఆగస్టు 2024')
on conflict (scheme_id, lang) do update set
    name = EXCLUDED.name,
    sponsoring_ministry = EXCLUDED.sponsoring_ministry,
    department = EXCLUDED.department,
    scheme_type = EXCLUDED.scheme_type,
    benefit_summary = EXCLUDED.benefit_summary,
    funding_range_text = EXCLUDED.funding_range_text,
    required_documents = EXCLUDED.required_documents,
    last_verified_date = EXCLUDED.last_verified_date;
insert into public.scheme_translations (scheme_id, lang, name, sponsoring_ministry, department, scheme_type, benefit_summary, funding_range_text, required_documents, last_verified_date)
values ('pm-mudra-tarun', 'te', 'ప్రధాన మంత్రి ముద్రా యోజన (తరుణ్ & కిశోర్ రుణం)', 'ఆర్థిక మంత్రిత్వ శాఖ (ఆర్థిక సేవల విభాగం)', 'మైక్రో యూనిట్స్ డెవలప్‌మెంట్ & రీఫైనాన్స్ ఏజెన్సీ (MUDRA)', 'రాయితీ రుణం', 'ఎటువంటి ఆస్తి పూచీకత్తు లేకుండా ₹50,000 నుండి ₹10 లక్షల వరకు వర్కింగ్ క్యాపిటల్ మరియు యంత్రాల రుణం.', '₹50,000 – ₹10,00,000', ARRAY['ముద్రా దరఖాస్తు ఫారమ్', 'గుర్తింపు మరియు నివాస ధృవీకరణ పత్రం', 'యంత్రాలు / సామగ్రి కొటేషన్ (వర్తిస్తే)', 'గత 6 నెలల బ్యాంకు ఖాతా స్టేట్‌మెంట్'], 'ఆగస్టు 2024')
on conflict (scheme_id, lang) do update set
    name = EXCLUDED.name,
    sponsoring_ministry = EXCLUDED.sponsoring_ministry,
    department = EXCLUDED.department,
    scheme_type = EXCLUDED.scheme_type,
    benefit_summary = EXCLUDED.benefit_summary,
    funding_range_text = EXCLUDED.funding_range_text,
    required_documents = EXCLUDED.required_documents,
