insert into public.scheme_translations (scheme_id, lang, name, sponsoring_ministry, department, scheme_type, benefit_summary, funding_range_text, required_documents, last_verified_date)
values ('cgtmse-guarantee', 'te', 'సూక్ష్మ మరియు చిన్న తరహా పరిశ్రమల క్రెడిట్ గ్యారెంటీ ఫండ్ ట్రస్ట్ (CGTMSE)', 'సూక్ష్మ, చిన్న & మధ్య తరహా పరిశ్రమల మంత్రిత్వ శాఖ (MSME)', 'క్రెడిట్ గ్యారెంటీ ట్రస్ట్ (సిడ్బీ & MSME)', 'క్రెడిట్ గ్యారెంటీ', 'మహిళలు, ఎస్సీ/ఎస్టీ వ్యవస్థాపకులకు ₹5 కోట్ల వరకు పూచీకత్తు లేని రుణాలపై 85% వరకు క్రెడిట్ గ్యారెంటీ.', '₹5,00,000 – ₹5,00,00,000', ARRAY['ఉద్యమ్ రిజిస్ట్రేషన్ సర్టిఫికేట్', 'ప్రమోటర్ల పాన్ మరియు ఆధార్ కార్డు', 'ప్రాజెక్ట్ సాధ్యత నివేదిక', 'జీఎస్టీ రిటర్నులు & బ్యాంక్ ఖాతా స్టేట్‌మెంట్'], 'ఆగస్టు 2024')
on conflict (scheme_id, lang) do update set
