insert into public.scheme_translations (scheme_id, lang, name, sponsoring_ministry, department, scheme_type, benefit_summary, funding_range_text, required_documents, last_verified_date)
values ('pmegp-msme', 'kn', 'ಪ್ರಧಾನ ಮಂತ್ರಿಗಳ ಉದ್ಯೋಗ ಸೃಜನ ಕಾರ್ಯಕ್ರಮ (PMEGP)', 'ಸೂಕ್ಷ್ಮ, ಸಣ್ಣ ಮತ್ತು ಮಧ್ಯಮ ಉದ್ಯಮಗಳ ಸಚಿವಾಲಯ (MSME)', 'ಖಾದಿ ಮತ್ತು ಗ್ರಾಮೋದ್ಯೋಗ ಆಯೋಗ (KVIC)', 'ಸಾಲ + ಸಬ್ಸಿಡಿ', 'ಹೊಸ ಸೂಕ್ಷ್ಮ ಉದ್ಯಮಗಳಿಗೆ ₹50 ಲಕ್ಷದವರೆಗೆ ಬ್ಯಾಂಕ್ ಸಾಲ ಮತ್ತು 35% ವರೆಗೆ ನೇರ ಬಂಡವಾಳ ಸಬ್ಸಿಡಿ.', '₹2,00,000 – ₹50,00,000', ARRAY['ಆಧಾರ್ ಕಾರ್ಡ್', 'ಜಾತಿ / ಸಮುದಾಯ ಪ್ರಮಾಣಪತ್ರ (SC/ST/OBC/Minority)', 'ವಿವರವಾದ ಯೋಜನಾ ವರದಿ (DPR)', 'ಉದ್ಯಮಶೀಲತಾ ತರಬೇತಿ (EDP) ಪ್ರಮಾಣಪತ್ರ', 'ಬ್ಯಾಂಕ್ ಪಾಸ್‌ಬುಕ್ ಮತ್ತು ಶೈಕ್ಷಣಿಕ ಅರ್ಹತಾ ದಾಖಲೆ'], 'ಆಗಸ್ಟ್ 2024')
on conflict (scheme_id, lang) do update set
    name = EXCLUDED.name,
    sponsoring_ministry = EXCLUDED.sponsoring_ministry,
    department = EXCLUDED.department,
    scheme_type = EXCLUDED.scheme_type,
    benefit_summary = EXCLUDED.benefit_summary,
    funding_range_text = EXCLUDED.funding_range_text,
