    last_verified_date = EXCLUDED.last_verified_date;
insert into public.scheme_translations (scheme_id, lang, name, sponsoring_ministry, department, scheme_type, benefit_summary, funding_range_text, required_documents, last_verified_date)
values ('standup-india', 'kn', 'ಪರಿಶಿಷ್ಟ ಜಾತಿ/ಪಂಗಡ ಮತ್ತು ಮಹಿಳಾ ಉದ್ಯಮಿಗಳಿಗಾಗಿ ಸ್ಟ್ಯಾಂಡ್-ಅಪ್ ಇಂಡಿಯಾ ಯೋಜನೆ', 'ಹಣಕಾಸು ಸಚಿವಾಲಯ ಮತ್ತು ಸಿಡ್ಬಿ (SIDBI)', 'ಹಣಕಾಸು ಸೇವೆಗಳ ಇಲಾಖೆ', 'ರಿಯಾಯಿತಿ ಸಾಲ', 'ಉತ್ಪಾದನೆ, ಸೇವೆ ಅಥವಾ ವ್ಯಾಪಾರ ಕ್ಷೇತ್ರಗಳಲ್ಲಿ ಹೊಸ ಘಟಕಗಳಿಗೆ 15% ರಿಯಾಯಿತಿ ಮಾರ್ಜಿನ್‌ನೊಂದಿಗೆ ₹10 ಲಕ್ಷದಿಂದ ₹1 ಕೋಟಿವರೆಗೆ ಸಾಲ.', '₹10,00,000 – ₹1,00,00,000', ARRAY['ಆಧಾರ್ ಮತ್ತು ಪ್ಯಾನ್ ಕಾರ್ಡ್', 'ಜಾತಿ ಪ್ರಮಾಣಪತ್ರ (SC/ST) / ಮಹಿಳಾ ಗುರುತಿನ ಪುರಾವೆ', 'ವ್ಯವಹಾರದ ಸ್ಥಳ / ಜಮೀನಿನ ಪುರಾವೆ', 'ಪುರಸಭೆ / ಮಾಲಿನ್ಯ ನಿಯಂತ್ರಣ ನಿರಾಕ್ಷೇಪಣಾ ಪತ್ರ (NOC)', 'ವಿವರವಾದ ಯೋಜನಾ ವರದಿ (DPR)'], 'ಜುಲೈ 2024')
on conflict (scheme_id, lang) do update set
    name = EXCLUDED.name,
    sponsoring_ministry = EXCLUDED.sponsoring_ministry,
    department = EXCLUDED.department,
    scheme_type = EXCLUDED.scheme_type,
    benefit_summary = EXCLUDED.benefit_summary,
    funding_range_text = EXCLUDED.funding_range_text,
    required_documents = EXCLUDED.required_documents,
    last_verified_date = EXCLUDED.last_verified_date;
insert into public.scheme_translations (scheme_id, lang, name, sponsoring_ministry, department, scheme_type, benefit_summary, funding_range_text, required_documents, last_verified_date)
values ('pm-vishwakarma', 'kn', 'ಸಾಂಪ್ರದಾಯಿಕ ಕುಶಲಕರ್ಮಿಗಳಿಗಾಗಿ ಪಿಎಂ ವಿಶ್ವಕರ್ಮ ಯೋಜನೆ', 'ಸೂಕ್ಷ್ಮ, ಸಣ್ಣ ಮತ್ತು ಮಧ್ಯಮ ಉದ್ಯಮಗಳ ಸಚಿವಾಲಯ (MSME)', 'ಕೌಶಲ್ಯ ಅಭಿವೃದ್ಧಿ ಮತ್ತು ಉದ್ಯಮಶೀಲತೆ ಸಚಿವಾಲಯ', 'ರಿಯಾಯಿತಿ ಸಾಲ', 'ಯಾವುದೇ ಭದ್ರತೆ ಇಲ್ಲದೆ 5% ರಿಯಾಯಿತಿ ಬಡ್ಡಿಯಲ್ಲಿ ₹3 ಲಕ್ಷದವರೆಗೆ ಸಾಲ ಮತ್ತು ₹15,000 ಮೌಲ್ಯದ ಆಧುನಿಕ ಉಪಕರಣಗಳ ಸಹಾಯ.', '₹1,00,000 – ₹3,00,000', ARRAY['ಆಧಾರ್ ಕಾರ್ಡ್', 'ಸಾಂಪ್ರದಾಯಿಕ ಕುಶಲಕರ್ಮಿ ಕೌಶಲ್ಯ ಪರಿಶೀಲನೆ (ಗ್ರಾಮ ಪಂಚಾಯಿತಿ / ಸ್ಥಳೀಯ ಸಂಸ್ಥೆ)', 'ಆಧಾರ್ ಲಿಂಕ್ ಆದ ಮೊಬೈಲ್ ಸಂಖ್ಯೆ', 'ಸಕ್ರಿಯ ಬ್ಯಾಂಕ್ ಖಾತೆ ವಿವರ'], 'ಆಗಸ್ಟ್ 2024')
on conflict (scheme_id, lang) do update set
