insert into public.scheme_translations (scheme_id, lang, name, sponsoring_ministry, department, scheme_type, benefit_summary, funding_range_text, required_documents, last_verified_date)
values ('pm-mudra-tarun', 'kn', 'ಪ್ರಧಾನ ಮಂತ್ರಿ ಮುದ್ರಾ ಯೋಜನೆ (ತರುಣ್ & ಕಿಶೋರ್ ಸಾಲ)', 'ಹಣಕಾಸು ಸಚಿವಾಲಯ (ಹಣಕಾಸು ಸೇವೆಗಳ ಇಲಾಖೆ)', 'ಮೈಕ್ರೋ ಯೂನಿಟ್ಸ್ ಡೆವಲಪ್‌ಮೆಂಟ್ & ರಿಫೈನಾನ್ಸ್ ಏಜೆನ್ಸಿ (MUDRA)', 'ರಿಯಾಯಿತಿ ಸಾಲ', 'ಯಾವುದೇ ಆಸ್ತಿ ಅಡಮಾನವಿಲ್ಲದೆ ₹50,000 ರಿಂದ ₹10 ಲಕ್ಷದವರೆಗೆ ದುಡಿಯುವ ಬಂಡವಾಳ ಮತ್ತು ಯಂತ್ರೋಪಕರಣಗಳ ಸಾಲ.', '₹50,000 – ₹10,00,000', ARRAY['ಮುದ್ರಾ ಅರ್ಜಿ ಫಾರ್ಮ್', 'ಗುರುತು ಮತ್ತು ವಿಳಾಸದ ಪುರಾವೆ', 'ಯಂತ್ರೋಪಕರಣಗಳ ಕೊಟೇಶನ್ (ಅನ್ವಯಿಸಿದರೆ)', 'ಕಳೆದ 6 ತಿಂಗಳ ಬ್ಯಾಂಕ್ ಖಾತೆ ವಿವರ'], 'ಆಗಸ್ಟ್ 2024')
