insert into public.scheme_translations (scheme_id, lang, name, sponsoring_ministry, department, scheme_type, benefit_summary, funding_range_text, required_documents, last_verified_date)
values ('cgtmse-guarantee', 'kn', 'ಸೂಕ್ಷ್ಮ ಮತ್ತು ಸಣ್ಣ ಉದ್ಯಮಗಳ ಕ್ರೆಡಿಟ್ ಗ್ಯಾರಂಟಿ ಫಂಡ್ ಟ್ರಸ್ಟ್ (CGTMSE)', 'ಸೂಕ್ಷ್ಮ, ಸಣ್ಣ ಮತ್ತು ಮಧ್ಯಮ ಉದ್ಯಮಗಳ ಸಚಿವಾಲಯ (MSME)', 'ಕ್ರೆಡಿಟ್ ಗ್ಯಾರಂಟಿ ಟ್ರಸ್ಟ್ (ಸಿಡ್ಬಿ & MSME)', 'ಕ್ರೆಡಿಟ್ ಗ್ಯಾರಂಟಿ', 'ಮಹಿಳೆಯರು ಮತ್ತು ಎಸ್‌ಸಿ/ಎಸ್‌ಟಿ ಉದ್ಯಮಿಗಳಿಗೆ ₹5 ಕೋಟಿವರೆಗಿನ ಅಡಮಾನ ರಹಿತ ಸಾಲಗಳಿಗೆ 85% ರವರೆಗೆ ಕ್ರೆಡಿಟ್ ಗ್ಯಾರಂಟಿ.', '₹5,00,000 – ₹5,00,00,000', ARRAY['ಉದ್ಯಮ್ ನೋಂದಣಿ ಪ್ರಮಾಣಪತ್ರ', 'ಪ್ರವರ್ತಕರ ಪ್ಯಾನ್ ಮತ್ತು ಆಧಾರ್ ಕಾರ್ಡ್', 'ಯೋಜನಾ ಕಾರ್ಯಸಾಧ್ಯತಾ ವರದಿ', 'ಜಿಎಸ್‌ಟಿ ರಿಟರ್ನ್ಸ್ ಮತ್ತು ಬ್ಯಾಂಕ್ ಸ್ಟೇಟ್‌ಮೆಂಟ್'], 'ಆಗಸ್ಟ್ 2024')
on conflict (scheme_id, lang) do update set
    name = EXCLUDED.name,
    sponsoring_ministry = EXCLUDED.sponsoring_ministry,
    department = EXCLUDED.department,
    scheme_type = EXCLUDED.scheme_type,
    benefit_summary = EXCLUDED.benefit_summary,
    funding_range_text = EXCLUDED.funding_range_text,
    required_documents = EXCLUDED.required_documents,
    last_verified_date = EXCLUDED.last_verified_date;
insert into public.scheme_translations (scheme_id, lang, name, sponsoring_ministry, department, scheme_type, benefit_summary, funding_range_text, required_documents, last_verified_date)
values ('pmegp-msme', 'ml', 'പ്രധാനമന്ത്രിയുടെ തൊഴിൽദായക പദ്ധതി (PMEGP)', 'സൂക്ഷ്മ, ചെറുകിട, ഇടത്തരം സംരംഭക മന്ത്രാലയം (MSME)', 'ഖാദി ആന്റ് വില്ലേജ് ഇൻഡസ്ട്രീസ് കമ്മീഷൻ (KVIC)', 'വായ്പ + സബ്‌സിഡി', 'പുതിയ സൂക്ഷ്മ സംരംഭങ്ങൾക്ക് ₹50 ലക്ഷം വരെ ബാങ്ക് വായ്പയും 35% വരെ നേരിട്ടുള്ള മൂലധന സബ്‌സിഡിയും.', '₹2,00,000 – ₹50,00,000', ARRAY['ആധാർ കാർഡ്', 'ജാതി / സമുദായ സർട്ടിഫിക്കറ്റ് (SC/ST/OBC/Minority)', 'വിശദമായ പ്രോജക്റ്റ് റിപ്പോർട്ട് (DPR)', 'സംരംഭകത്വ പരിശീലന (EDP) സർട്ടിഫിക്കറ്റ്', 'ബാങ്ക് പാസ്സ്ബുക്കും വിദ്യാഭ്യാസ യോഗ്യതാ രേഖകളും'], 'ഓഗസ്റ്റ് 2024')
on conflict (scheme_id, lang) do update set
    name = EXCLUDED.name,
    sponsoring_ministry = EXCLUDED.sponsoring_ministry,
    department = EXCLUDED.department,
    scheme_type = EXCLUDED.scheme_type,
    benefit_summary = EXCLUDED.benefit_summary,
    funding_range_text = EXCLUDED.funding_range_text,
    required_documents = EXCLUDED.required_documents,
    last_verified_date = EXCLUDED.last_verified_date;
insert into public.scheme_translations (scheme_id, lang, name, sponsoring_ministry, department, scheme_type, benefit_summary, funding_range_text, required_documents, last_verified_date)
values ('standup-india', 'ml', 'പട്ടികജാതി/വർഗ്ഗ, വനിതാ സംരംഭകർക്കായുള്ള സ്റ്റാൻഡ്-അപ്പ് ഇന്ത്യ പദ്ധതി', 'ധനകാര്യ മന്ത്രാലയം & സിഡ്ബി (SIDBI)', 'സാമ്പത്തിക സേവന വകുപ്പ്', 'ഇളവ് വായ്പ', 'നിർമ്മാണം, സർവീസ് അല്ലെങ്കിൽ വ്യാപാര മേഖലകളിൽ പുതിയ സംരംഭങ്ങൾക്ക് 15% ഇളവ് മാർജിനോടെ ₹10 ലക്ഷം മുതൽ ₹1 കോടി വരെ വായ്പ.', '₹10,00,000 – ₹1,00,00,000', ARRAY['ആധാർ, പാൻ കാർഡുകൾ', 'ജാതി സർട്ടിഫിക്കറ്റ് (SC/ST) / വനിതാ തിരിച്ചറിയൽ രേഖ', 'ബിസിനസ്സ് സ്ഥലം / ഭൂമി രേഖകൾ', 'മുനിസിപ്പാലിറ്റി / മലിനീകരണ നിയന്ത്രണ ബോർഡ് എൻഒസി (NOC)', 'വിശദമായ പ്രോജക്റ്റ് റിപ്പോർട്ട് (DPR)'], 'ജൂലൈ 2024')
on conflict (scheme_id, lang) do update set
    name = EXCLUDED.name,
    sponsoring_ministry = EXCLUDED.sponsoring_ministry,
    department = EXCLUDED.department,
    scheme_type = EXCLUDED.scheme_type,
    benefit_summary = EXCLUDED.benefit_summary,
    funding_range_text = EXCLUDED.funding_range_text,
    required_documents = EXCLUDED.required_documents,
    last_verified_date = EXCLUDED.last_verified_date;
insert into public.scheme_translations (scheme_id, lang, name, sponsoring_ministry, department, scheme_type, benefit_summary, funding_range_text, required_documents, last_verified_date)
values ('pm-vishwakarma', 'ml', 'പരമ്പരാഗത തൊഴിലാളികൾക്കായുള്ള പിഎം വിശ്വകർമ പദ്ധതി', 'സൂക്ഷ്മ, ചെറുകിട, ഇടത്തരം സംരംഭക മന്ത്രാലയം (MSME)', 'നൈപുണ്യ വികസന, സംരംഭകത്വ മന്ത്രാലയം', 'ഇളവ് വായ്പ', 'ഈടില്ലാതെ 5% ഇളവ് പലിശ നിരക്കിൽ ₹3 ലക്ഷം വരെ വായ്പയും ₹15,000 മൂല്യമുള്ള അത്യാധുനിക ടൂൾകിറ്റ് സഹായവും.', '₹1,00,000 – ₹3,00,000', ARRAY['ആധാർ കാർഡ്', 'പരമ്പരാഗത കരകൗശല തൊഴിലാളി സാക്ഷ്യപ്പെടുത്തൽ (ഗ്രാമപഞ്ചായത്ത് / നഗരസഭ)', 'ആധാറുമായി ബന്ധിപ്പിച്ച മൊബൈൽ നമ്പർ', 'സജീവ ബാങ്ക് അക്കൗണ്ട് വിവരങ്ങൾ'], 'ഓഗസ്റ്റ് 2024')
on conflict (scheme_id, lang) do update set
    name = EXCLUDED.name,
    sponsoring_ministry = EXCLUDED.sponsoring_ministry,
    department = EXCLUDED.department,
    scheme_type = EXCLUDED.scheme_type,
    benefit_summary = EXCLUDED.benefit_summary,
    funding_range_text = EXCLUDED.funding_range_text,
    required_documents = EXCLUDED.required_documents,
    last_verified_date = EXCLUDED.last_verified_date;
